import React, { FC, useEffect, useState } from 'react';
import styled from 'styled-components';
import Heading from '@splunk/react-ui/Heading';
import Link from '@splunk/react-ui/Link';
import Message from '@splunk/react-ui/Message';
import WaitSpinner from '@splunk/react-ui/WaitSpinner';
import { createDocsURL } from '@splunk/splunk-utils/url';
import SUIFormRenderer, { ISubmitHandler, Errors } from '@splunk/sui-form-renderer';
import { pick, variables } from '@splunk/themes';
import { flowRight as compose } from 'lodash';

import {
    addDelDashboardUrl,
    fetchDashboardsTrustedDomainsList,
} from './DashboardsTrustedDomainsList.apiservice';
import { getWarningMessage } from './DashboardsTrustedDomainsList.utils';
import { DASHBOARDS_TRUSTED_DOMAINS_LIST_LOC_STR } from './DashboardsTrustedDomainsList.constants';
import { DashboardsTrustedDomainsListFormData } from './DashboardsTrustedDomainsList.interfaces';
import { customValidators } from './DashboardsTrustedDomainsList.custom-validators';
import { schema } from './data/jsonforms/schema';
import { uiSchema } from './data/jsonforms/uischema';
import { MESSAGES } from '../../messages';
import TEST_IDS from './DashboardsTrustedDomainsList.testids';
import { withRBACFilter } from '../../shared/components/FilterHOCs/filterHOCs';

const WaitSpinnerWrapper = styled.div`
    display: flex;
    justify-content: center;
    margin-top: 40px;
    margin-bottom: 40px;
`;

const WrapperDiv = styled.div`
    max-width: 960px;
    padding: 30px 20px 20px 20px;
    background-color: ${pick({
        enterprise: variables.backgroundColor,
        prisma: variables.backgroundColorPopup,
    })};
    box-shadow: ${variables.overlayShadow};
    margin: 0 auto 20px;
    display: flex;
    flex-direction: column;
`;

const DashboardsTrustedDomainsList: FC = () => {
    const [formData, setFormData] = useState<DashboardsTrustedDomainsListFormData>({
        'dashboard-values': [],
    });

    const [errorMessages, setErrorMessages] = useState<string[]>([]);
    const [notEnforcedMsg, setNotEnforcedMsg] = useState<string>('');
    const [isLoading, setIsLoading] = useState(true);

    useEffect(() => {
        (async (): Promise<void> => {
            const { records, errors, dashboardFlags } = await fetchDashboardsTrustedDomainsList();
            setNotEnforcedMsg(getWarningMessage(dashboardFlags));

            if (records && records.length) {
                setFormData({
                    'dashboard-values': records,
                });
            }

            if (errors.length) {
                setErrorMessages(errors);
            }

            setIsLoading(false);
        })();
    }, []);

    const handleSubmit: ISubmitHandler<DashboardsTrustedDomainsListFormData> = async ({
        data,
        successCb,
        failureCb,
    }) => {
        const { records, errors } = await addDelDashboardUrl(data);
        // If no records were updated, do nothing
        if (!records && !errors?.length) {
            return;
        }

        // Update records only if present. For error cases, we don't want to re-render the forms to preserve the user input that caused errors
        if (errors.length) {
            failureCb(errors);
        } else {
            setFormData({
                'dashboard-values': records,
            });
            successCb();
        }
    };

    const renderListEnforced = (): JSX.Element => {
        return (
            <Message appearance="fill" type="warning">
                {MESSAGES.DASHBOARDS_TRUSTED_DOMAINS_LIST[notEnforcedMsg]}
                <Link to={createDocsURL(DASHBOARDS_TRUSTED_DOMAINS_LIST_LOC_STR)} openInNewContext>
                    {MESSAGES.COMMON.LEARN_MORE}
                </Link>
            </Message>
        );
    };

    return (
        <>
            {!isLoading && (
                <WrapperDiv data-test-name={TEST_IDS.CONTAINER}>
                    {!!notEnforcedMsg && renderListEnforced()}
                    <p>
                        {MESSAGES.DASHBOARDS_TRUSTED_DOMAINS_LIST.DESCRIPTION}
                        <Link
                            to={createDocsURL(DASHBOARDS_TRUSTED_DOMAINS_LIST_LOC_STR)}
                            openInNewContext
                            data-test-name={TEST_IDS.LEARN_MORE_LINK}
                        >
                            {MESSAGES.COMMON.LEARN_MORE}
                        </Link>
                    </p>
                    <Heading>{MESSAGES.DASHBOARDS_TRUSTED_DOMAINS_LIST.TRUSTED_DOMAINS}</Heading>
                    {errorMessages.length > 0 && <Errors errorMessages={errorMessages} />}
                    {!errorMessages.length && (
                        <SUIFormRenderer
                            schema={schema}
                            uischema={uiSchema}
                            data={formData}
                            onSubmit={handleSubmit}
                            customValidators={customValidators}
                        />
                    )}
                </WrapperDiv>
            )}
            {isLoading && (
                <WaitSpinnerWrapper data-test-name={TEST_IDS.WAITSPINNER}>
                    <WaitSpinner size="medium" />
                </WaitSpinnerWrapper>
            )}
        </>
    );
};

const DTDL = compose([withRBACFilter(['edit_dashboard_allow_list'])])(DashboardsTrustedDomainsList);

export default DTDL;
